function countElements(arr) {
  let total = 0;
  for (let i = 0; i < arr.length; i++) {
    let found = false;
    for (let j = 0; j < arr.length; j++) if (arr[j] === arr[i] + 1) found = true;
    if (found) total++;
  }
  return total;
}

